pub fn score_bin(
    item_size: u32,
    bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    // Base score: remaining space after placement
    let mut score = post_residual as f64;

    // 1. Tight‑fit reward – stronger weight
    if next_item_size > 0 {
        let diff_next = (post_residual as i32 - next_item_size as i32).abs() as f64;
        score -= diff_next * 1.8;
    }

    // 2. Residual proximity to mean – adaptive weight
    let diff_mean = (post_residual as f64 - mean_residual).abs();
    let mean_weight = 0.8 * (1.0 / (open_bins_count as f64 + 1.0));
    score += diff_mean * mean_weight;

    // 3. New‑bin penalties / bonuses
    if bin_residual == bin_capacity {
        let waste_new = bin_capacity - item_size;
        if waste_new > 60 && next_item_size < 10 {
            score += waste_new as f64 * 0.12;
        }
        if open_bins_count > 12 {
            score += 10.0;
        }
        if waste_new < 5 {
            score -= 0.7;
        }
    }

    // 4. Sole fitting bin penalty (unless new)
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score += 3.5;
    }

    // 5. Progress‑dependent adjustment
    let progress = step_index as f64 / total_items as f64;
    let progress_factor = if progress > 0.90 { 0.10 } else { 0.05 };
    score += (1.0 - progress) * post_residual as f64 * progress_factor;

    // 6. Quadratic waste penalty for large residuals
    if post_residual > 50 {
        score += (post_residual as f64).powi(2) * 0.00007;
    }

    // 7. Lookahead check – penalize if next item cannot fit
    if next_item_size > 0 && post_residual < next_item_size {
        score += 2.5;
    }

    // 8. Bonus for bins that are nearly empty when many bins are open
    if open_bins_count > 5 && post_residual < 8 {
        score -= 0.3;
    }

    // 9. Residual‑ratio penalty / reward
    let ratio = post_residual as f64 / bin_capacity as f64;
    if ratio > 0.5 {
        score += ratio * 3.0;
    } else {
        score -= 0.2 * (0.5 - ratio);
    }

    // 10. Additional penalty for large residuals with large next item
    if bin_residual != bin_capacity
        && post_residual > 40
        && next_item_size > 25
    {
        score += 1.5;
    }

    // 11. Slight penalty for many open bins with moderate residual
    if open_bins_count > 15 && post_residual > 20 {
        score += 0.5;
    }

    score
}

